export function sampleRipple(distance, age) {
  if (age < 0 || age > 3) return 0;
  const speed = 1.5;
  const radius = speed * age;
  const diff = distance - radius;
  const sigma = 0.5;
  const envelope = Math.exp(-diff * diff / (2 * sigma * sigma));
  const wave = Math.sin(2 * Math.PI * diff / 0.3);
  let amp = envelope * wave;
  if (amp > 0.04) amp = 0.04;
  if (amp < -0.04) amp = -0.04;
  return amp;
}
